def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        queue = []
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                queue.remove(key)
                queue.append(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                queue.append(key)
                if len(queue) > maxsize:
                    cache.pop(queue.pop(0))
                return result
        return wrapper
    return decorator
