def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    key = key(*args, **kwargs)
                    if key not in cache:
                        cache[key] = func(*args, **kwargs)
            else:
                key = key(*args, **kwargs)
                if key not in cache:
                    cache[key] = func(*args, **kwargs)
            return cache[key]
        return wrapper
    return decorator
