def formatmany(self, sql, many_params):
    formatted_sql = sql
    out_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            out_params.append(self._format_named_params(params))
        elif isinstance(params, Sequence):
            out_params.append(self._format_ordinal_params(params))
        else:
            raise ValueError("Invalid parameter type")
    return formatted_sql, out_params

def _format_named_params(self, params):
    formatted_params = {}
    for key, value in params.items():
        formatted_params[key] = self._format_param(value)
    return formatted_params

def _format_ordinal_params(self, params):
    formatted_params = []
    for value in params:
        formatted_params.append(self._format_param(value))
    return formatted_params

def _format_param(self, value):
    if isinstance(value, str):
        return "'{}'".format(value)
    elif isinstance(value, int):
        return str(value)
    else:
        raise ValueError("Invalid parameter type")
