        raise IRValidatorException("Spec content is required")
    spec_data = yaml.safe_load(spec_content)
    if "name" not in spec_data:
        raise IRValidatorException("Name is a mandatory field in the spec")
    if "version" not in spec_data:
        raise IRValidatorException("Version is a mandatory field in the spec")
    if "description" not in spec_data:
        raise IRValidatorException("Description is a mandatory field in the spec")
    return spec_data
